mkdir -p /app/output && cat > /app/output/index.html <<'HTML'
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>WellSource — Trusted Health & Wellness</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    :root {
      --brand-700: oklch(44% 0.11 184);
      --brand-600: oklch(52% 0.10 182);
      --brand-500: oklch(60% 0.09 181);
      --brand-300: oklch(82% 0.05 178);
      --accent-coral: oklch(72% 0.14 35);
      --accent-amber: oklch(80% 0.13 80);
      --bg-main: oklch(98% 0.01 120);
      --bg-muted: oklch(95% 0.01 170);
      --surface: oklch(100% 0 0);
      --text-900: oklch(26% 0.02 210);
      --text-700: oklch(40% 0.02 210);
      --text-500: oklch(55% 0.02 210);
      --border: oklch(88% 0.01 200);
      --shadow-soft: 0 10px 30px oklch(40% 0.02 210 / 0.08);
      --radius: 16px;
      --container: min(1200px, 92vw);
    }

    * { box-sizing: border-box; }
    body {
      margin: 0;
      font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
      color: var(--text-900);
      background: linear-gradient(180deg, var(--bg-main) 0%, var(--bg-muted) 100%);
      line-height: 1.5;
    }
    a { color: inherit; text-decoration: none; }
    img { max-width: 100%; display: block; }

    .container { width: var(--container); margin: 0 auto; }

    .top-ticker {
      background: var(--brand-700);
      color: white;
      padding: 0.65rem 0;
      overflow: hidden;
      position: sticky;
      top: 0;
      z-index: 40;
    }
    .ticker-track {
      display: flex;
      gap: 3rem;
      width: max-content;
      animation: ticker 24s linear infinite;
      will-change: transform;
      font-weight: 600;
      font-size: 0.95rem;
      letter-spacing: 0.01em;
    }
    .ticker-item { opacity: 0.95; }
    @keyframes ticker {
      from { transform: translateX(0); }
      to { transform: translateX(-50%); }
    }

    header {
      background: oklch(100% 0 0 / 0.9);
      backdrop-filter: blur(8px);
      border-bottom: 1px solid var(--border);
      position: sticky;
      top: 40px;
      z-index: 30;
    }
    .nav-row {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 2rem;
      padding: 1rem 0;
      position: relative;
    }
    .brand {
      font-size: 1.35rem;
      font-weight: 800;
      color: var(--brand-700);
      letter-spacing: -0.02em;
    }
    .main-nav {
      display: flex;
      gap: 0.35rem;
      flex-wrap: wrap;
      align-items: center;
    }
    .nav-btn {
      border: 0;
      background: transparent;
      color: var(--text-700);
      font-weight: 600;
      font-size: 0.95rem;
      padding: 0.55rem 0.8rem;
      border-radius: 10px;
      cursor: pointer;
    }
    .nav-btn:hover, .nav-btn[aria-expanded="true"] {
      background: var(--bg-muted);
      color: var(--brand-700);
    }

    .mega-menu {
      position: absolute;
      left: 0;
      right: 0;
      top: calc(100% + 0.5rem);
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      box-shadow: var(--shadow-soft);
      padding: 1.1rem;
      display: none;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 1rem;
      z-index: 50;
    }
    .mega-menu.open { display: grid; }
    .menu-col {
      background: var(--bg-main);
      border-radius: 12px;
      padding: 0.9rem;
    }
    .menu-col h4 {
      margin: 0 0 0.45rem;
      font-size: 0.95rem;
      color: var(--brand-700);
    }
    .menu-col a {
      display: block;
      padding: 0.3rem 0;
      color: var(--text-700);
      font-size: 0.9rem;
    }

    .hero {
      padding: 3rem 0 2rem;
      display: grid;
      grid-template-columns: 1.8fr 1fr;
      gap: 1.3rem;
    }
    .card {
      background: var(--surface);
      border-radius: var(--radius);
      border: 1px solid var(--border);
      box-shadow: var(--shadow-soft);
    }
    .hero-main { padding: 1.4rem; }
    .eyebrow { color: var(--brand-700); font-weight: 700; font-size: 0.78rem; letter-spacing: 0.06em; text-transform: uppercase; }
    h1 { margin: 0.4rem 0 0.9rem; line-height: 1.1; font-size: clamp(1.8rem, 3vw, 2.7rem); }
    .lead { color: var(--text-700); font-size: 1.05rem; margin-bottom: 1.1rem; }
    .cta-row { display: flex; flex-wrap: wrap; gap: 0.7rem; }
    .btn {
      border: 0;
      border-radius: 999px;
      padding: 0.7rem 1rem;
      font-weight: 700;
      cursor: pointer;
      font-size: 0.9rem;
    }
    .btn-primary { background: var(--accent-coral); color: oklch(24% 0.02 18); }
    .btn-secondary { background: var(--bg-muted); color: var(--text-900); }

    .trending { padding: 1.1rem; }
    .trending h3 { margin: 0 0 0.8rem; font-size: 1.05rem; }
    .trend-item { padding: 0.72rem 0; border-top: 1px solid var(--border); }
    .trend-item:first-of-type { border-top: 0; }
    .tag { font-size: 0.72rem; font-weight: 700; color: var(--brand-600); text-transform: uppercase; letter-spacing: 0.05em; }

    section { margin: 1.6rem 0; }
    .section-head {
      display: flex;
      justify-content: space-between;
      align-items: end;
      gap: 1rem;
      margin-bottom: 0.9rem;
    }
    .section-head h2 { margin: 0; font-size: 1.55rem; }
    .section-head p { margin: 0; color: var(--text-700); }

    .topics-wrap { position: relative; }
    .topics-track {
      display: grid;
      grid-auto-flow: column;
      grid-auto-columns: minmax(140px, 1fr);
      overflow-x: auto;
      gap: 0.9rem;
      scroll-behavior: smooth;
      padding: 0.2rem 2.8rem;
      scrollbar-width: none;
    }
    .topics-track::-webkit-scrollbar { display: none; }
    .topic-card {
      text-align: center;
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 999px;
      padding: 0.8rem;
      box-shadow: var(--shadow-soft);
    }
    .topic-card img {
      width: 86px;
      height: 86px;
      border-radius: 50%;
      object-fit: cover;
      margin: 0 auto 0.55rem;
      border: 3px solid var(--bg-muted);
    }
    .carousel-btn {
      position: absolute;
      top: 50%;
      transform: translateY(-50%);
      width: 2.2rem;
      height: 2.2rem;
      border-radius: 50%;
      border: 1px solid var(--border);
      background: var(--surface);
      box-shadow: var(--shadow-soft);
      cursor: pointer;
      z-index: 3;
    }
    .carousel-btn.left { left: 0; }
    .carousel-btn.right { right: 0; }

    .tools-grid, .reads-grid, .pillars-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 1rem;
    }
    .tool, .read, .pillar { padding: 1rem; }
    .tool h3, .read h3, .pillar h3 { margin: 0 0 0.5rem; font-size: 1.03rem; }
    .tool p, .read p, .pillar p { margin: 0; color: var(--text-700); font-size: 0.92rem; }

    .tabs {
      display: flex;
      gap: 0.5rem;
      flex-wrap: wrap;
      margin-bottom: 1rem;
    }
    .tab {
      border: 1px solid var(--border);
      background: var(--surface);
      color: var(--text-700);
      border-radius: 999px;
      padding: 0.5rem 0.85rem;
      font-weight: 600;
      cursor: pointer;
      font-size: 0.88rem;
    }
    .tab.active { background: var(--brand-600); color: white; border-color: transparent; }

    .newsletter {
      background: linear-gradient(120deg, oklch(90% 0.05 180), oklch(93% 0.05 65));
      border: 1px solid oklch(82% 0.05 170);
      border-radius: 20px;
      padding: 1.2rem;
      display: grid;
      grid-template-columns: 1.2fr 1fr;
      gap: 1rem;
      align-items: center;
    }
    .newsletter form {
      display: flex;
      gap: 0.6rem;
      flex-wrap: wrap;
      justify-content: end;
    }
    .newsletter input {
      flex: 1 1 230px;
      border: 1px solid var(--border);
      border-radius: 999px;
      padding: 0.72rem 0.95rem;
      font: inherit;
      min-width: 220px;
    }
    .newsletter-note { font-size: 0.84rem; color: var(--text-700); margin-top: 0.45rem; }

    footer {
      margin-top: 2.2rem;
      padding: 2rem 0;
      color: var(--text-500);
      font-size: 0.9rem;
      border-top: 1px solid var(--border);
    }

    @media (max-width: 980px) {
      header { top: 38px; }
      .hero { grid-template-columns: 1fr; }
      .tools-grid, .reads-grid, .pillars-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
      .newsletter { grid-template-columns: 1fr; }
      .newsletter form { justify-content: start; }
    }
    @media (max-width: 640px) {
      .main-nav { gap: 0.1rem; }
      .nav-btn { padding: 0.48rem 0.5rem; font-size: 0.87rem; }
      .mega-menu { grid-template-columns: 1fr; }
      .tools-grid, .reads-grid, .pillars-grid { grid-template-columns: 1fr; }
      .topics-track { padding: 0.2rem 2.2rem; }
    }
  </style>
</head>
<body>
  <div class="top-ticker" aria-label="Credibility stats ticker">
    <div class="container">
      <div class="ticker-track" id="tickerTrack">
        <span class="ticker-item">✔ Medically reviewed content</span>
        <span class="ticker-item">✔ 145 medical reviewers in network</span>
