  <footer>
    <div class="container">© 2026 WellSource. Editorial content is for informational purposes and not a substitute for professional medical advice.</div>
  </footer>

  <script>
    const menuData = {
      health: {
        title: 'Health Conditions',
        columns: {
          'Common Conditions': ['Type 2 Diabetes', 'Heart Disease', 'Asthma', 'Arthritis'],
          'Life Stages': ['Women\'s Health', 'Menopause', 'Aging Well', 'Teen Health'],
          'By Body System': ['Digestive Health', 'Skin Health', 'Immune System', 'Hormonal Health']
        }
      },
      wellness: {
        title: 'Wellness',
        columns: {
          'Mental Well-Being': ['Stress Management', 'Depression Support', 'Sleep Science', 'Mindfulness'],
          'Fitness': ['Strength Training', 'Cardio Basics', 'Mobility', 'Recovery'],
          'Nutrition': ['Healthy Eating', 'Supplements', 'Hydration', 'Meal Planning']
        }
      },
      tools: {
        title: 'Tools',
        columns: {
          'Calculators': ['Calorie Calculator', 'Macronutrient Calculator', 'BMI Calculator', 'Water Intake'],
          'Directories': ['Drug Directory: A to Z', 'FindCare', 'Specialist Finder', 'Insurance Basics'],
          'Trackers': ['Habit Tracker', 'Symptom Journal', 'Medication Reminders', 'Sleep Tracker']
        }
      },
      featured: {
        title: 'Featured',
        columns: {
          'Editor\'s Picks': ['Top Reads This Week', 'Most Shared Stories', 'Expert Interviews', 'Deep Dives'],
          'Seasonal': ['Allergy Season Guide', 'Cold & Flu Preparedness', 'Summer Skin Care', 'Winter Fitness'],
          'Community': ['Reader Stories', 'Success Journeys', 'Ask an Expert', 'Q&A Highlights']
        }
      },
      connect: {
        title: 'Connect',
        columns: {
          'Newsletters': ['Daily Brief', 'Weekly Wellness', 'Condition Guides', 'Product Roundups'],
          'Follow': ['Instagram', 'YouTube', 'Podcast', 'X / Twitter'],
          'Support': ['Contact Us', 'Advertise', 'Editorial Policy', 'Accessibility']
        }
      }
    };

    const navButtons = document.querySelectorAll('.nav-btn');
    const megaMenu = document.getElementById('megaMenu');

    function renderMenu(menuKey) {
      const menu = menuData[menuKey];
      if (!menu) return;
      megaMenu.innerHTML = Object.entries(menu.columns).map(([heading, links]) => `
        <div class="menu-col">
          <h4>${heading}</h4>
          ${links.map(link => `<a href="index.html">${link}</a>`).join('')}
        </div>
      `).join('');
    }

    navButtons.forEach(btn => {
      btn.addEventListener('click', () => {
        const isOpen = btn.getAttribute('aria-expanded') === 'true';
        navButtons.forEach(b => b.setAttribute('aria-expanded', 'false'));
        if (isOpen) {
          megaMenu.classList.remove('open');
          return;
        }
        renderMenu(btn.dataset.menu);
        megaMenu.classList.add('open');
        btn.setAttribute('aria-expanded', 'true');
      });
    });

    document.addEventListener('click', (event) => {
      if (!event.target.closest('.nav-row')) {
        megaMenu.classList.remove('open');
        navButtons.forEach(b => b.setAttribute('aria-expanded', 'false'));
      }
    });

    const topicsTrack = document.getElementById('topicsTrack');
    document.getElementById('topicsPrev').addEventListener('click', () => topicsTrack.scrollBy({ left: -280, behavior: 'smooth' }));
    document.getElementById('topicsNext').addEventListener('click', () => topicsTrack.scrollBy({ left: 280, behavior: 'smooth' }));

    const readsData = {
      'Top Reads': [
        ['16 Superfoods That Are Worthy of the Title', 'Nutrition essentials backed by current evidence.'],
        ['Does Ozempic Cause Hair Loss?', 'What experts say about side effects and expectations.'],
        ['Can Music Therapy Help with Depression?', 'A look at research on emotional and mental outcomes.'],
        ['These Are the 8 Best Calorie Counter Apps', 'Comparison of features, pricing, and ease of use.']
      ],
      'Fitness': [
        ['Build a Sustainable Workout Habit in 30 Days', 'How to start small and stay consistent.'],
        ['The Truth About Zone 2 Cardio', 'What it is and who benefits most.'],
        ['Mobility Drills for Desk Workers', 'Simple routines to reduce stiffness and pain.'],
        ['Protein Timing: Myth vs Reality', 'What matters most for recovery and strength.']
      ],
      'Mental Well-Being': [
        ['Can Music Therapy Help with Depression?', 'A look at research on emotional and mental outcomes.'],
        ['5 Grounding Techniques for Anxiety', 'Quick tools you can use anytime, anywhere.'],
        ['How to Build a Better Sleep Routine', 'Practical shifts for deeper, longer sleep.'],
        ['When to Seek Professional Help', 'Signs it may be time to connect with a clinician.']
      ],
      'Product Reviews': [
        ['These Are the 8 Best Calorie Counter Apps', 'Comparison of features, pricing, and ease of use.'],
        ['Best Smart Scales for 2026', 'How accurate are body composition metrics?'],
        ['Air Purifiers for Allergy Season', 'Top options across budget tiers.'],
        ['Compression Boots: Worth It?', 'Benefits, risks, and buying considerations.']
      ],
      'Recipes': [
        ['High-Protein Breakfasts in 15 Minutes', 'Fast ideas for busy mornings.'],
        ['Heart-Healthy One-Pan Dinners', 'Lower sodium meals packed with flavor.'],
        ['Mediterranean Lunch Prep Guide', 'Build balanced lunches for the whole week.'],
        ['No-Bake Fiber-Rich Snacks', 'Smart snacking without added fuss.']
      ],
      'Skin Care': [
        ['Derm-Approved Skin Routine Basics', 'The minimum effective routine, simplified.'],
        ['How to Repair a Damaged Skin Barrier', 'Signs to watch and products to prioritize.'],
        ['SPF Myths That Need to Go', 'What dermatologists want you to know.'],
        ['Does Diet Affect Acne?', 'Exploring links between nutrition and breakouts.']
      ]
    };

    const tabsRoot = document.getElementById('tabs');
    const readsGrid = document.getElementById('readsGrid');

    function renderReads(category) {
      const data = readsData[category] || [];
      readsGrid.innerHTML = data.map(([title, desc]) => `
        <article class="card read">
          <h3>${title}</h3>
          <p>${desc}</p>
        </article>
      `).join('');
    }

    Object.keys(readsData).forEach((tabName, index) => {
      const button = document.createElement('button');
