        ['No-Bake Fiber-Rich Snacks', 'Smart snacking without added fuss.']
      ],
      'Skin Care': [
        ['Derm-Approved Skin Routine Basics', 'The minimum effective routine, simplified.'],
        ['How to Repair a Damaged Skin Barrier', 'Signs to watch and products to prioritize.'],
        ['SPF Myths That Need to Go', 'What dermatologists want you to know.'],
        ['Does Diet Affect Acne?', 'Exploring links between nutrition and breakouts.']
      ]
    };

    const tabsRoot = document.getElementById('tabs');
    const readsGrid = document.getElementById('readsGrid');

    function renderReads(category) {
      const data = readsData[category] || [];
      readsGrid.innerHTML = data.map(([title, desc]) => `
        <article class="card read">
          <h3>${title}</h3>
          <p>${desc}</p>
        </article>
      `).join('');
    }

    Object.keys(readsData).forEach((tabName, index) => {
      const button = document.createElement('button');
      button.className = `tab ${index === 0 ? 'active' : ''}`;
      button.textContent = tabName;
      button.addEventListener('click', () => {
        [...tabsRoot.children].forEach(t => t.classList.remove('active'));
        button.classList.add('active');
        renderReads(tabName);
      });
      tabsRoot.appendChild(button);
    });
    renderReads('Top Reads');

    const newsletterForm = document.getElementById('newsletterForm');
    const newsletterMessage = document.getElementById('newsletterMessage');
    newsletterForm.addEventListener('submit', (event) => {
      event.preventDefault();
      const email = document.getElementById('emailInput').value.trim();
      if (!email) return;
      newsletterMessage.textContent = `Thanks! ${email} is now subscribed to Weekly Wellness Brief.`;
      newsletterForm.reset();
    });
  </script>
